object Solution {
  def twoSum(nums: Array[Int], target: Int): Array[Int] = {
    val seen = mutable.HashMap.empty[Int, Int]
    for (i <- nums.indices) {
      val need = target - nums(i)
      seen.get(need) match {
        case Some(j) => return Array(j, i)
        case None    => seen(nums(i)) = i
      }
    }
    Array.emptyIntArray
  }
